USE smart_travel_db;
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE activity a JOIN course_day d ON d.id=a.course_day_id JOIN course c ON c.id=d.course_id JOIN place p ON p.place_id=a.place_id SET a.place_name=p.name,a.title=p.name,a.address_snapshot=p.address,a.latitude_snapshot=p.latitude,a.longitude_snapshot=p.longitude WHERE c.member_no=(SELECT member_id FROM members WHERE login_id='user1') AND JSON_UNQUOTE(JSON_EXTRACT(c.condition_meta,'$.fixture')) LIKE 'MYPAGE-USER1-%' AND p.is_active=TRUE AND p.latitude IS NOT NULL AND p.longitude IS NOT NULL;
UPDATE mypage_course_draft SET days_json=JSON_SET(days_json,'$[0].mapPlaces',JSON_ARRAY((SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=106 AND is_active=TRUE),(SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=118 AND is_active=TRUE))) WHERE id=1 AND member_id=(SELECT member_id FROM members WHERE login_id='user1') AND client_id='mypage-user1-saved-202612-1';
UPDATE mypage_course_draft SET days_json=JSON_SET(days_json,'$[1].mapPlaces',JSON_ARRAY((SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=119 AND is_active=TRUE),(SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=120 AND is_active=TRUE))) WHERE id=1 AND member_id=(SELECT member_id FROM members WHERE login_id='user1') AND client_id='mypage-user1-saved-202612-1';
UPDATE mypage_course_draft SET days_json=JSON_SET(days_json,'$[0].mapPlaces',JSON_ARRAY((SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=9590 AND is_active=TRUE),(SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=9592 AND is_active=TRUE))) WHERE id=2 AND member_id=(SELECT member_id FROM members WHERE login_id='user1') AND client_id='mypage-user1-saved-202612-2';
UPDATE mypage_course_draft SET days_json=JSON_SET(days_json,'$[1].mapPlaces',JSON_ARRAY((SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=9595 AND is_active=TRUE),(SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=9600 AND is_active=TRUE))) WHERE id=2 AND member_id=(SELECT member_id FROM members WHERE login_id='user1') AND client_id='mypage-user1-saved-202612-2';
UPDATE mypage_course_draft SET days_json=JSON_SET(days_json,'$[0].mapPlaces',JSON_ARRAY((SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=8787 AND is_active=TRUE),(SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=8826 AND is_active=TRUE))) WHERE id=3 AND member_id=(SELECT member_id FROM members WHERE login_id='user1') AND client_id='mypage-user1-saved-202612-3';
UPDATE mypage_course_draft SET days_json=JSON_SET(days_json,'$[1].mapPlaces',JSON_ARRAY((SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=8859 AND is_active=TRUE),(SELECT JSON_OBJECT('placeId',place_id,'name',name,'address',address,'latitude',latitude,'longitude',longitude) FROM place WHERE place_id=8860 AND is_active=TRUE))) WHERE id=3 AND member_id=(SELECT member_id FROM members WHERE login_id='user1') AND client_id='mypage-user1-saved-202612-3';
COMMIT;
SELECT COUNT(*) AS mapped_activities FROM activity WHERE place_id IS NOT NULL AND latitude_snapshot IS NOT NULL AND longitude_snapshot IS NOT NULL; SELECT id,JSON_LENGTH(JSON_EXTRACT(days_json,'$[0].mapPlaces')) first_day_markers,JSON_LENGTH(JSON_EXTRACT(days_json,'$[1].mapPlaces')) second_day_markers FROM mypage_course_draft WHERE client_id LIKE 'mypage-user1-saved-202612-%';